CREATE TABLE IF NOT EXISTS notification_settings(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,product_added INTEGER NOT NULL DEFAULT 1,product_changed INTEGER NOT NULL DEFAULT 1,product_purchased INTEGER NOT NULL DEFAULT 1,product_restored INTEGER NOT NULL DEFAULT 1,product_deleted INTEGER NOT NULL DEFAULT 1,list_deleted INTEGER NOT NULL DEFAULT 1,list_renamed INTEGER NOT NULL DEFAULT 1,member_joined INTEGER NOT NULL DEFAULT 1,member_removed INTEGER NOT NULL DEFAULT 1,role_changed INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,list_id TEXT REFERENCES lists(id) ON DELETE CASCADE,type TEXT NOT NULL,actor_user_id TEXT REFERENCES users(id),payload TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_events_list_created ON events(list_id,created_at DESC);